"""Tests for Streamlit dashboard artifact loaders and utility functions."""

import pytest
import pandas as pd
from app.utils import (
    load_pipeline_summary,
    load_data_audit,
    load_model_comparison,
    load_review_comparison,
    load_analysis_summary,
    load_calibration_metrics,
    load_detection_metrics,
    load_final_test_metrics,
    load_hyperparameter_trials,
    load_tuning_summary,
    mask_sensitive_text,
)


class TestDashboardLoaders:
    """Verify all dashboard loaders retrieve actual artifacts generated by pipeline."""

    def test_pipeline_summary_loads(self):
        summary = load_pipeline_summary()
        assert summary is not None
        assert "pipeline_version" in summary
        assert summary["dataset_records"] in (16338, 50000)

    def test_data_audit_loads(self):
        audit = load_data_audit()
        assert audit is not None
        assert "dataset_summary" in audit
        assert audit["dataset_summary"]["total_rows"] in (16338, 50000)
        assert audit["text_statistics"]["char_length_mean"] > 0
        assert audit["text_statistics"]["word_count_mean"] > 0

    def test_model_comparison_loads(self):
        df = load_model_comparison()
        assert df is not None
        assert isinstance(df, pd.DataFrame)
        assert len(df) >= 3
        assert "macro_f1" in df.columns

    def test_review_comparison_loads(self):
        df = load_review_comparison()
        assert df is not None
        assert isinstance(df, pd.DataFrame)
        assert "errors_per_100" in df.columns
        assert len(df) == 3

    def test_analysis_summary_loads(self):
        summary = load_analysis_summary()
        assert summary is not None
        assert "overall_noise" in summary
        assert "transition_matrix" in summary

    def test_calibration_metrics_loads(self):
        cal = load_calibration_metrics()
        assert cal is not None
        assert "ece" in cal
        assert "mean_brier" in cal

    def test_detection_metrics_loads(self):
        det = load_detection_metrics()
        assert det is not None
        assert "precision_at_100" in det
        assert "average_precision" in det

    def test_final_test_metrics_loads(self):
        test_m = load_final_test_metrics()
        assert test_m is not None
        assert "metrics" in test_m
        assert "accuracy" in test_m["metrics"]

    def test_hyperparameter_trials_loads(self):
        trials_df = load_hyperparameter_trials()
        assert trials_df is not None
        assert isinstance(trials_df, pd.DataFrame)
        assert len(trials_df) >= 10
        assert "macro_f1" in trials_df.columns
        assert "model_family" in trials_df.columns

    def test_tuning_summary_loads(self):
        summary = load_tuning_summary()
        assert summary is not None
        assert "best_trial" in summary
        assert "top_5_trials" in summary
        assert summary["best_trial"]["macro_f1"] > 0.60


class TestPrivacyMasking:
    """Verify sensitive text redaction helper."""

    def test_email_redaction(self):
        text = "Contact me at alice.smith@example.com for order help."
        masked = mask_sensitive_text(text)
        assert "[EMAIL REDACTED]" in masked
        assert "alice.smith@example.com" not in masked

    def test_phone_redaction(self):
        text = "Call customer at +1 555-123-4567 immediately."
        masked = mask_sensitive_text(text)
        assert "[PHONE REDACTED]" in masked

    def test_length_truncation(self):
        long_text = "a" * 500
        masked = mask_sensitive_text(long_text, max_chars=100)
        assert len(masked) == 103  # 100 + "..."
        assert masked.endswith("...")
